INSERT INTO articles VALUES('sdsul01-004','sdsul01',15,'A transparência do Museu das Missões',NULL,'pt-BR',NULL,13,'sdsul01-004.pdf',NULL,NULL,NULL,NULL,NULL,NULL,'["COSTA, Lucio. Registro de uma Vivência. São Paulo: Empresa das Artes, 1995.", "COSTA, Lucio. Sobre Arquitetura. Porto Alegre: CEAU, 1962.", "Transparency and Architecture. Journal of Architectural Education, Washington, v. 56, May 2003.", "LUZ, Maturino. Lucio Costa no Sul: o Museu das Missões. Cadernos de Arquitetura Ritter dos Reis, Porto Alegre, v. 2, p. 25-45, out. 2000.", "MAYERHOFER, Lucas. Reconstituição do Povo de São Miguel das Missões. Tese de Concurso para Provimento da Cadeira de Arquitetura Analítica da Faculdade Nacional de Arquitetura. Rio de Janeiro, 1947.", "PESSOA, José (org.). Lucio Costa: Documentos de Trabalho. Rio de Janeiro: IPHAN, 1999.", "ROWE, Colin. The Mathematics of the Ideal Villa and Other Essays. Cambridge, MA: The MIT Press, 1995."]',NULL,NULL,'artigo',NULL,NULL,'','',NULL);
INSERT INTO articles VALUES('sdsul01-005','sdsul01',15,'Simples abrigo, límpida ruína, Modernidade real','o Museu das Missões de Lucio Costa','pt-BR',NULL,9,'sdsul01-005.pdf',NULL,NULL,NULL,NULL,NULL,NULL,'["COSTA, Lucio. Relatório sobre as Missões de 23-12-1937. In: PESSOA, José (org.). Lucio Costa: Documentos de Trabalho. Rio de Janeiro: IPHAN, 1999.", "VIOLLET-LE-DUC, Eugène Emmanuel. Restauração. São Paulo: Ateliê Editorial, 2000.", "ROWE, Colin; SLUTZKY, Robert. Transparency: Literal and Phenomenal. In: ROWE, Colin. The Mathematics of the Ideal Villa and Other Essays. Cambridge, MA: MIT Press, 1976.", "HITCHCOCK, Henry-Russell; JOHNSON, Philip. The International Style. New York: MoMA, 1932.", "GOODWIN, Philip; KIDDER-SMITH, George. Brazil Builds: New Architecture and Old 1652-1942. New York: MoMA, 1943.", "MORAES, Rubens Borba de. Domingo dos Séculos. São Paulo: Oficina de Imprensa Rubens Borba de Moraes, 1924.", "JENCKS, Charles. Modern Movements in Architecture. Garden City, New York: Anchor Press, 1973.", "BACON, Edmund. The Design of Cities. New York: Viking Press, 1974."]',NULL,NULL,'artigo',NULL,NULL,'','',NULL);
