INSERT INTO articles VALUES('sdsp08-002','sdsp08',70,'João Walter Toscano a partir de seu acervo',NULL,'pt-BR','22-30',9,'sdsp08-002.pdf',NULL,NULL,NULL,NULL,NULL,NULL,'["COSTA, Alexandre Alves. “João Walter Toscano: da indispensabilidade de construir: pensar é experimentar” [1999]. In: ARTIGAS, Rosa (org.). João Walter Toscano. São Paulo: Editora UNESP; Instituto Takano, 2002.", "COSTA, Eduardo Augusto. Mudanças epistemológicas na arquitetura: entre arquivos e publicações. Estudos Históricos, Rio de Janeiro, vol. 34, n. 72, p. 129-147, jan. /abr. 2021. Disponível em: <https://doi.org/10.1590/S2178-149420210107>. Acesso em 21 ago. 2022.", "COSTA, Eduardo Augusto. Lucio Costa na Europa: o papel dos acervos e a arquitetura brasileira. Novos Estudos - CEBRAP, São Paulo, vol. 41, n. 2, p.371-386, mai. / ago. 2022. Disponível em: <https://doi.org/10.25091/S01013300202200020010>. Acesso em 15 set. 2022.", "LIRA, José T. C. (coord.). Acervos de arquitetos da FAUUSP: coleção João Toscano. São Paulo: LPG; FAUUSP, 2019.", "LIRA, José T. C, et. al. Acervos de arquitetura como espaço histórico de formação. Anais do Museu Paulista: História e Cultura Material, São Paulo, vol. 29, nov. 2021. Disponível em: <https://doi.org/10.1590/1982- 02672021v29e53>. Acesso em 20 ago. 2022."]',NULL,NULL,'artigo',NULL,NULL,'','',NULL);
INSERT INTO articles VALUES('sdsp08-003','sdsp08',70,'O arquiteto Ubyrajara Gilioli',NULL,'pt-BR','31-42',12,'sdsp08-003.pdf',NULL,NULL,NULL,NULL,NULL,NULL,'["FERRATA, C. A. Escolas públicas em São Paulo (1960-1972). Dissertação (Mestrado em Arquitetura e Urbanismo). Faculdade de Arquitetura e Urbanismo da Universidade de São Paulo. São Paulo, 2008.", "GILIOLI, U. Arquitetura e Lugar. Tese (Doutorado em Arquitetura e Urbanismo). Faculdade de Arquitetura e Urbanismo da Universidade de São Paulo. São Paulo, 1994.", "GILIOLI, U. Construções escolares. Revista Projeto, nº 7, 1978. Disponível para assinantes em: https://revistaprojeto.com.br/acervo/construcoes- escolares-por-ubyrajara-gilioli/ Acesso em 08 ago. 2022.", "GILIOLI, U. Escola, São Paulo. Revista Projeto, nº 7, 1978. Disponível para assinantes em: https://revistaprojeto.com.br/acervo/ubyrajara-gilioli- escola-sao-23-05-2006/ Acesso em 08 ago. 2022.", "GILIOLI, U. Centro de Reabilitação da Polícia Militar. Revista Projeto, nº 7, 1978. Disponível para assinantes em:", "https://revistaprojeto.com.br/acervo/ubyrajara-gilioli-centro-de-15-02- 2008/ Acesso em 08 ago. 2022.", "GRUPO Escolar de Ferrazopolis. Acrópole, São Paulo, ano 31, n. 3365, p. 32-33, set. 1969 Disponível em http://www.acropole.fau.usp.br/edicao/365/34 Acesso em 14 de jun. 2022.", "SILVA, J. L. S. A Escola Paulista e a função social da arquitetura: projetos escolares entre 1959 e 1975. 2022. Dissertação (Mestrado em Teoria e História da Arquitetura e do Urbanismo) - Instituto de Arquitetura e Urbanismo, Universidade de São Paulo, São Carlos, 2022. doi:10.11606/D.102.2022.tde-19092022-152709. Acesso em: 2022-10-07."]',NULL,NULL,'artigo',NULL,NULL,'','',NULL);
