PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE article_author (
    article_id TEXT NOT NULL REFERENCES articles(id),
    author_id INTEGER NOT NULL REFERENCES authors(id),
    seq INTEGER DEFAULT 0,
    primary_contact INTEGER DEFAULT 0,
    affiliation TEXT,
    bio TEXT,
    country TEXT DEFAULT 'BR',
    PRIMARY KEY (article_id, author_id)
);
CREATE TABLE articles (
    id TEXT PRIMARY KEY,
    seminar_slug TEXT NOT NULL REFERENCES seminars(slug),
    section_id INTEGER REFERENCES sections(id),
    title TEXT NOT NULL,
    subtitle TEXT,
    locale TEXT DEFAULT 'pt-BR',
    pages TEXT,
    pages_count INTEGER,
    file TEXT,
    abstract TEXT,
    abstract_en TEXT,
    abstract_es TEXT,
    keywords TEXT,
    keywords_en TEXT,
    keywords_es TEXT,
    references_ TEXT,
    ojs_id TEXT,
    doi TEXT
, document_type TEXT DEFAULT 'artigo', title_en TEXT, subtitle_en TEXT, title_es TEXT DEFAULT "", subtitle_es TEXT DEFAULT "", zenodo_record_id TEXT);
