CREATE TABLE author_variants (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    author_id INTEGER NOT NULL REFERENCES authors(id),
    givenname TEXT NOT NULL,
    familyname TEXT NOT NULL,
    source TEXT,
    UNIQUE(givenname, familyname)
);
CREATE TABLE authors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    givenname TEXT NOT NULL,
    familyname TEXT NOT NULL,
    email TEXT,
    orcid TEXT, orcid_checked_at TEXT, orcid_pipeline_version TEXT,
    UNIQUE(givenname, familyname)
);
CREATE TABLE dict_names (
        word TEXT PRIMARY KEY,
        category TEXT NOT NULL,  -- 'nome', 'sigla', 'lugar', 'area', 'movimento', 'expressao'
        canonical TEXT,          -- forma canônica (ex: 'Le Corbusier' para expressão)
        source TEXT              -- origem: 'autores', 'manual', 'lugares', etc.
    );
CREATE TABLE orcid_exclusions (
    author_id INTEGER NOT NULL REFERENCES authors(id),
    orcid TEXT NOT NULL,
    reason TEXT,
    PRIMARY KEY (author_id, orcid)
);
CREATE TABLE sections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    seminar_slug TEXT NOT NULL REFERENCES seminars(slug),
    title TEXT NOT NULL,
    abbrev TEXT,
    seq INTEGER DEFAULT 0, hide_title INTEGER DEFAULT 0,
    UNIQUE(seminar_slug, title)
);
CREATE TABLE seminars (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    subtitle TEXT,
    year INTEGER NOT NULL,
    volume INTEGER,
    number INTEGER,
    date_published TEXT,
    isbn TEXT,
    doi TEXT,
    description TEXT,
    location TEXT,
    publisher TEXT,
    source TEXT,
    editors TEXT
, volume_pdf TEXT, related_urls TEXT, section_label TEXT DEFAULT 'sessão', zenodo_doi TEXT, zenodo_record_id TEXT, volume_pdf_label TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_articles_seminar ON articles(seminar_slug);
CREATE INDEX idx_articles_section ON articles(section_id);
CREATE INDEX idx_sections_seminar ON sections(seminar_slug);
CREATE INDEX idx_article_author_author ON article_author(author_id);
CREATE INDEX idx_article_author_article ON article_author(article_id);
CREATE INDEX idx_author_variants_author ON author_variants(author_id);
CREATE INDEX idx_authors_familyname ON authors(familyname);
COMMIT;
